-- ===================================================
-- Flyway Migration V9: Institutional Student Cohort Placements & Debarment Log
-- Direct from JECRC University Training & Placement Cell (1,630 Students + 84 Absentees)
-- ===================================================

CREATE TABLE student_placement_records (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    roll_number VARCHAR(50) NOT NULL,
    student_name VARCHAR(150) NOT NULL,
    section VARCHAR(50),
    mentor VARCHAR(150),
    email VARCHAR(150),
    mobile VARCHAR(50),
    gender VARCHAR(20),
    placement_status VARCHAR(50) NOT NULL DEFAULT 'ENROLLED',
    college VARCHAR(150),
    program VARCHAR(50),
    course VARCHAR(150),
    eligible_profiles INT DEFAULT 0,
    not_eligible_profiles INT DEFAULT 0,
    eligible_during_window INT DEFAULT 0,
    total_applications INT DEFAULT 0,
    ppt_count INT DEFAULT 0,
    screening_count INT DEFAULT 0,
    gd_count INT DEFAULT 0,
    pi_count INT DEFAULT 0,
    other_stages_count INT DEFAULT 0,
    attempts_count INT DEFAULT 0,
    offers_count INT DEFAULT 0,
    placed_company VARCHAR(150),
    placed_role_title VARCHAR(255),
    placed_profile_opened VARCHAR(255),
    ctc VARCHAR(100),
    ctc_lpa NUMERIC(6, 2),
    ppo VARCHAR(20),
    job_location VARCHAR(150),
    sector VARCHAR(150),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_spr_roll ON student_placement_records(roll_number);
CREATE INDEX idx_spr_status ON student_placement_records(placement_status);
CREATE INDEX idx_spr_course ON student_placement_records(course);
CREATE INDEX idx_spr_mentor ON student_placement_records(mentor);
CREATE INDEX idx_spr_placed_co ON student_placement_records(placed_company);

INSERT INTO student_placement_records (
    roll_number, student_name, section, mentor, email, mobile, gender, placement_status,
    college, program, course, eligible_profiles, not_eligible_profiles, eligible_during_window,
    total_applications, ppt_count, screening_count, gd_count, pi_count, other_stages_count,
    attempts_count, offers_count, placed_company, placed_role_title, placed_profile_opened,
    ctc, ctc_lpa, ppo, job_location, sector
) VALUES
