CREATE TABLE placement_debarment_records (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    roll_number VARCHAR(50) NOT NULL,
    student_name VARCHAR(150) NOT NULL,
    section VARCHAR(50),
    mentor VARCHAR(150),
    program VARCHAR(50),
    college VARCHAR(150),
    course VARCHAR(150),
    absent_count INT DEFAULT 1,
    companies_details TEXT,
    penalty_status VARCHAR(50) DEFAULT 'ACTIVE_PENALTY',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_pdr_roll ON placement_debarment_records(roll_number);
CREATE INDEX idx_pdr_mentor ON placement_debarment_records(mentor);

